const express = require('express');
const app = express();
const _ = require('lodash');

// Configuration store - merged from defaults and user preferences
let appConfig = {
  theme: 'light',
  locale: 'en-US',
  notifications: { email: true, push: false },
  display: { density: 'comfortable', fontSize: 14 }
};

// Serve the main page with dynamically loaded scripts
app.get('/', (req, res) => {
  const cdnBase = process.env.CDN_BASE_URL || 'https://cdn.example.com';
  res.send(`
    <!DOCTYPE html>
    <html>
    <head>
      <title>Dashboard</title>
      <script src="${cdnBase}/vendor/lodash-4.17.21.min.js"></script>
      <script src="${cdnBase}/vendor/analytics-2.3.0.js"></script>
      <script src="${cdnBase}/app/config-loader.js"></script>
    </head>
    <body>
      <div id="app"></div>
      <script src="${cdnBase}/app/main.js"></script>
    </body>
    </html>
  `);
});

// API endpoint to update user preferences via deep merge
app.put('/api/preferences', express.json(), (req, res) => {
  const userPrefs = req.body;

  // Validate top-level keys exist in config
  const allowedKeys = Object.keys(appConfig);
  const providedKeys = Object.keys(userPrefs);
  const hasValidKeys = providedKeys.some(k => allowedKeys.includes(k));

  if (!hasValidKeys && providedKeys.length > 0) {
    return res.status(400).json({ error: 'Invalid preference keys' });
  }

  // Deep merge user preferences into app config
  // Note: lodash merge is used for nested object support
  _.merge(appConfig, userPrefs);

  res.json({ success: true, config: appConfig });
});

// API endpoint to get current config (used by config-loader.js on frontend)
app.get('/api/config', (req, res) => {
  res.json(appConfig);
});

// Health check for ECS
app.get('/health', (req, res) => {
  res.json({ status: 'healthy', uptime: process.uptime() });
});

// Template endpoint that renders config into page context
app.get('/api/widget-config', (req, res) => {
  const widgetId = req.query.id || 'default';
  const baseWidget = { id: widgetId, version: '1.0' };
  const merged = Object.assign({}, baseWidget, appConfig.display || {});

  // If prototype was polluted, toString/constructor properties leak here
  res.json(merged);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Service running on port ${PORT}`);
});

module.exports = app;
